<template><div class="page"><AppNav/><main class="collab"><aside class="side panel"><button class="primary wide" @click="createDialog=true">＋ 创建学习群</button><div class="side-title"><b>学习协作</b><button @click="friendDialog=true">添加好友</button></div><p class="label">我的会话</p><button v-for="item in conversations" :key="item.id" class="conversation" :class="{active:item.id===currentId}" @click="open(item.id)"><span>{{item.type==='group'?'◌':'◉'}}</span><div><b>{{item.title}}</b><small>{{item.last_message||'还没有消息'}}</small></div></button><p class="label">我的学习伙伴</p><div v-for="friend in friends" :key="friend.id" class="friend">● {{friend.name}} <small>{{friend.college}}</small></div><p v-if="requests.length" class="label">新的好友申请</p><div v-for="request in requests" :key="request.id" class="request">{{request.name}} <button @click="accept(request.id)">接受</button></div></aside><section class="chat panel"><template v-if="current"><header><div><span class="eyebrow">{{current.type==='group'?'STUDY GROUP':'PRIVATE CHAT'}}</span><h1>{{current.title}}</h1><p>{{current.member_count}} 位成员 · 群聊适合共建复习清单、分工和共享课程资料</p></div></header><div class="messages"><article v-for="message in messages" :key="message.id" :class="{mine:message.sender_id===me.id}"><b>{{message.sender_id===me.id?'我':message.sender_name}}</b><p>{{message.content}}</p></article><div v-if="!messages.length" class="empty">开始一段有目标的学习讨论吧。</div></div><form @submit.prevent="send"><input v-model="input" placeholder="输入学习讨论内容"/><button class="primary">发送</button></form></template><div v-else class="no-chat"><div>◌</div><h2>选择一个学习会话</h2><p>先添加伙伴，再创建复习群、项目组或课程讨论组。</p></div></section></main><el-dialog v-model="createDialog" title="创建学习群" width="440px"><el-form label-position="top"><el-form-item label="群名称"><el-input v-model="group.title" placeholder="如：数据结构期末复习小组"/></el-form-item><el-form-item label="邀请学习伙伴"><el-select v-model="group.member_ids" multiple style="width:100%"><el-option v-for="f in friends" :key="f.id" :label="f.name+' · '+f.college" :value="f.id"/></el-select></el-form-item></el-form><template #footer><button class="primary" @click="createGroup">创建群聊</button></template></el-dialog><el-dialog v-model="friendDialog" title="添加学习伙伴" width="440px"><el-input v-model="search" placeholder="输入姓名或学号搜索" @input="findUsers"/><div v-for="user in found" :key="user.id" class="found"><div><b>{{user.name}}</b><small>{{user.student_id}} · {{user.college}}</small></div><button @click="requestFriend(user.id)">添加</button></div></el-dialog></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import AppNav from'../components/AppNav.vue';import{api,post}from'../utils/api';const conversations=ref([]),friends=ref([]),requests=ref([]),messages=ref([]),currentId=ref(null),input=ref(''),createDialog=ref(false),friendDialog=ref(false),search=ref(''),found=ref([]),group=ref({title:'',member_ids:[]});const me=computed(()=>JSON.parse(localStorage.getItem('user')||'{}')),current=computed(()=>conversations.value.find(x=>x.id===currentId.value));async function load(){[conversations.value,friends.value,requests.value]=await Promise.all([api('/conversations'),api('/friends'),api('/friend-requests')]);if(conversations.value[0]&&!currentId.value)open(conversations.value[0].id)}async function open(id){currentId.value=id;messages.value=await api(`/conversations/${id}/messages`)}async function send(){if(!input.value.trim())return;try{await post(`/conversations/${currentId.value}/messages`,{content:input.value});input.value='';await open(currentId.value);load()}catch(e){ElMessage.error(e.message)}}async function createGroup(){try{const data=await post('/conversations',{...group.value,type:'group'});createDialog.value=false;group.value={title:'',member_ids:[]};await load();open(data.id)}catch(e){ElMessage.error(e.message)}}async function findUsers(){found.value=search.value.trim()?await api(`/users/search?q=${encodeURIComponent(search.value)}`):[]}async function requestFriend(id){try{await post('/friend-requests',{user_id:id});ElMessage.success('好友申请已发送')}catch(e){ElMessage.error(e.message)}}async function accept(id){await post(`/friend-requests/${id}/accept`,{});load()}onMounted(()=>load().catch(e=>ElMessage.error(e.message)))</script>
<style scoped>.collab{max-width:1280px;margin:auto;padding:28px 5vw;display:grid;grid-template-columns:300px 1fr;gap:20px;min-height:calc(100vh - 72px)}.panel{background:#fffdfa;border:1px solid #f1e2d8;border-radius:24px;box-shadow:0 10px 30px #9f4c2b0d}.side{padding:16px}.primary{background:#c96d42;color:white;border:0;border-radius:13px;padding:10px 15px;font-weight:700;cursor:pointer}.wide{width:100%}.side-title{display:flex;justify-content:space-between;margin:24px 2px 8px;color:#704330}.side-title button,.request button,.found button{border:0;background:#fff0e4;color:#ad5938;border-radius:9px;padding:6px;cursor:pointer}.label,.eyebrow{font-size:11px;letter-spacing:1.1px;color:#b18b78;font-weight:800;margin:20px 2px 8px}.conversation{display:flex;gap:9px;width:100%;border:0;background:transparent;border-radius:13px;padding:10px;text-align:left;color:#745e53;cursor:pointer}.conversation span{font-size:21px;color:#c96d42}.conversation small,.friend small,.found small{display:block;color:#a98c7e;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation.active,.conversation:hover{background:#fff0e5}.friend,.request{padding:7px;color:#786257;font-size:14px}.request{display:flex;justify-content:space-between}.chat{display:flex;flex-direction:column;min-height:600px}.chat header{padding:23px 28px}.chat h1{font-size:24px;color:#633c2c;margin:5px 0}.chat header p{color:#987b6d;margin:0;font-size:14px}.messages{flex:1;background:#fffaf6;border-top:1px solid #f2e5dc;border-bottom:1px solid #f2e5dc;padding:20px 28px;overflow:auto}.messages article{max-width:72%;margin:12px 0}.messages article.mine{margin-left:auto;text-align:right}.messages b{font-size:12px;color:#a8806c}.messages p{margin:4px 0;background:#f9ece3;border-radius:14px 14px 14px 3px;padding:10px 13px;color:#684839;text-align:left;line-height:1.55}.messages .mine p{background:#c96d42;color:#fff;border-radius:14px 14px 3px 14px}.chat form{display:flex;gap:9px;padding:15px 20px}.chat input{flex:1;border:1px solid #ead8cd;border-radius:13px;padding:11px;font:inherit}.no-chat{text-align:center;margin:auto;color:#a08475}.no-chat>div{font-size:50px;color:#c96d42}.found{display:flex;justify-content:space-between;align-items:center;padding:13px 4px;border-bottom:1px solid #f2e5dc}.found small{font-size:12px}@media(max-width:780px){.collab{grid-template-columns:1fr;padding:15px}.side{display:none}.chat{min-height:calc(100vh - 105px)}}</style>
